import{_ as s,o as n,c as p,a2 as t}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"5. 威胁模型与信任假设","description":"","frontmatter":{},"headers":[],"relativePath":"zh/publications/tmpa-core-specification-s1.0/part-03.md","filePath":"zh/publications/tmpa-core-specification-s1.0/part-03.md","lastUpdated":1786439037000}'),l={name:"zh/publications/tmpa-core-specification-s1.0/part-03.md"};function i(e,a,r,d,o,c){return n(),p("div",null,[...a[0]||(a[0]=[t(`<h2 id="_4-2-规范文本编码-profile" tabindex="-1">4.2 规范文本编码 Profile <a class="header-anchor" href="#_4-2-规范文本编码-profile" aria-label="Permalink to &quot;4.2 规范文本编码 Profile&quot;">​</a></h2><p>仅选择 JSON、YAML 或 Markdown 不能定义规范文本表示。只有当独立实现能够从同一受治理内容生成相同的被覆盖字节序列时，一个版本化规范化 Profile 才算完整。</p><p>该 Profile 至少 <strong>MUST</strong> 定义：</p><ul><li>字符编码与 Unicode 规范化形式；</li><li>换行符规范化；</li><li>对语义上无序字段与集合的确定性排序；</li><li>空白、转义、引号与分隔符规则；</li><li>数字表示，包括指数、符号与精度；</li><li>时间戳语法、时区要求与小数秒规范化；</li><li>缺失、<code>null</code>、空字符串与空集合的区别；</li><li>文本正文是否逐字节覆盖，或如何规范 Markdown 空白与换行；</li><li>附件与外部证据的媒体类型、字节长度、内容 Digest 与可选定位元数据；</li><li>扩展字段是否被 Digest/签名覆盖，以及未知扩展如何排序或拒绝；</li><li>与对象绑定的 Schema、类型注册表与规范化 Profile 版本；</li><li>Hash 或签名前如何排除或规范化自引用完整性字段。</li></ul><p>语义等价不足以完成完整性验证。Unicode 形式、换行、数字拼写、时间精度、字段顺序或扩展处理不同的对象，即使人类认为含义相同，也可能产生不同 Digest。因此，C08 与 C11 只有在使用同一规范化 Profile 及版本时才有意义。</p><p>外部附件或可变 URL 不会因被引用就自动成为权威证据。声称外部内容完整性的 Profile <strong>MUST</strong> 记录内容 Digest 以及识别被覆盖字节所需的元数据。Locator <strong>MAY</strong> 帮助检索，但 Locator 本身不能保存被引用证据。</p><h2 id="_4-3-聚合与治理重建程序" tabindex="-1">4.3 聚合与治理重建程序 <a class="header-anchor" href="#_4-3-聚合与治理重建程序" aria-label="Permalink to &quot;4.3 聚合与治理重建程序&quot;">​</a></h2><p>给定有限无序来源候选集合 <code>O</code> 与固定规则 Profile <code>P</code>，符合规范的实现执行两个阶段：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AGGREGATE(O):</span></span>
<span class="line"><span>  1. 发现每项来源工件，但不把发现顺序、文件系统顺序、</span></span>
<span class="line"><span>     传输顺序、修改时间赋予治理意义。</span></span>
<span class="line"><span>  2. 保留来源身份与字节并解析候选封装；</span></span>
<span class="line"><span>     解析失败仍作为来源证据和确定性诊断保留。</span></span>
<span class="line"><span>  3. 规范索引对象 ID、写者流、序号、主载体、引用、</span></span>
<span class="line"><span>     生命周期位置与完整性元数据。</span></span>
<span class="line"><span>  4. 投影时可以去重字节相同的来源观测，但不得删除 Provenance；</span></span>
<span class="line"><span>     相同 ID、不同内容必须作为不同候选保留。</span></span>
<span class="line"><span>  5. 返回保留来源的规范候选集合 C 与聚合诊断。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>RECONSTRUCT(C, P):</span></span>
<span class="line"><span>  1. 验证对象结构与文档类型；无效候选保留用于诊断，</span></span>
<span class="line"><span>     但排除在权威候选集合之外。</span></span>
<span class="line"><span>  2. 按声明的规范化 Profile 重算 Digest；Digest 不匹配对象</span></span>
<span class="line"><span>     作为完整性失败证据保留，但不得进入完整权威候选集合。</span></span>
<span class="line"><span>  3. 存在签名时验证签名，记录验证状态并应用 P 的接受策略；</span></span>
<span class="line"><span>     无法验证的签名不能建立认证完整性。</span></span>
<span class="line"><span>  4. 按对象 ID 对完整候选分组：</span></span>
<span class="line"><span>     a. 相同 ID、相同规范内容：投影为一个对象，同时按 Unicode 码点顺序保留每个贡献来源的 \`source_id\`；</span></span>
<span class="line"><span>     b. 相同 ID、不同规范内容：全部变体隔离，产生重复 ID 冲突。</span></span>
<span class="line"><span>  5. 验证面向任务 Profile 的一主载体规则；后续报告、复核、</span></span>
<span class="line"><span>     决策和更正必须引用载体，不得形成歧义的可变任务副本。</span></span>
<span class="line"><span>  6. 按写者流分组接受对象并依序号排序；检测重复序号与序号缺口，</span></span>
<span class="line"><span>     不得发明缺失对象，也不得用时间戳替代序号。</span></span>
<span class="line"><span>  7. 只为 P 声明为顺序或生命周期依赖的关系类型建立有向边；</span></span>
<span class="line"><span>     其他引用保留为非排序链接。</span></span>
<span class="line"><span>  8. 验证角色权限、职责分离、生命周期来源状态、迁移合法性、</span></span>
<span class="line"><span>     前置条件与必需证据；无效动作保持可观察但不改变权威状态。</span></span>
<span class="line"><span>  9. 检测缺失引用与 P 禁止的环；只隔离受影响子图，</span></span>
<span class="line"><span>     保留未受影响的有效对象。</span></span>
<span class="line"><span> 10. 从流内序号边与 Profile 定义的跨流依赖构造偏序流程与治理图；</span></span>
<span class="line"><span>     无关节点保持并发且不可比较。</span></span>
<span class="line"><span> 11. 交换或显示需要线性序列时，生成确定性拓扑序列；</span></span>
<span class="line"><span>     对象 ID 字典序只能作为不可比较节点的 Tie-break，</span></span>
<span class="line"><span>     不得把该关系加入治理图。</span></span>
<span class="line"><span> 12. 投影任务、消息、流程、责任、生命周期、复核、批准、恢复与审计视图。</span></span>
<span class="line"><span> 13. 规范化治理图/视图与问题集合，并将二者一起返回。</span></span></code></pre></div><p>组合运算为：</p><p><code>R_P(A(O)) = (G, I)</code></p><p>其中 <code>A(O)</code> 是保留来源的规范候选集合，<code>G</code> 是偏序流程与治理图，<code>I</code> 是规范问题集合。程序 <strong>MUST</strong> 保持以下不变量：</p><ul><li>对于同一来源集合，发现、枚举和到达顺序不影响最终规范输出；</li><li>聚合保留来源证据，不静默决定治理冲突；</li><li>面向任务的 Profile 中，一项受治理任务只有一个稳定主载体；</li><li>每个已发布对象只有一个写者并属于一条局部串行流；</li><li>时间戳不得覆盖流序号或显式依赖；</li><li>Profile 未定义因果或生命周期关系时，不得发明跨流顺序；</li><li>规范线性序列只是图的表示，不是额外治理事实；</li><li>invalid、disputed 或 rejected 证据不得被静默擦除；</li><li>冲突只能由新的授权治理对象解决；</li><li>同一规范来源集合与固定 Profile 产生同一候选集合、治理视图与问题集合；</li><li>partial 或 disputed 视图必须与 authoritative 视图区分。</li></ul><p>延迟证据会改变当前来源集合，因此可以合法改变当前视图。只有在最终来源集合相同时，确定性才要求相同输出；异步流程不同阶段的输出不必相同。</p><h2 id="_4-4-冲突与验证处理" tabindex="-1">4.4 冲突与验证处理 <a class="header-anchor" href="#_4-4-冲突与验证处理" aria-label="Permalink to &quot;4.4 冲突与验证处理&quot;">​</a></h2><p>Reader <strong>MUST</strong> 按以下规则稳定处理异常：</p><table tabindex="0"><thead><tr><th>条件</th><th>必需行为</th></tr></thead><tbody><tr><td>Schema 或类型无效</td><td>保留来源用于诊断，排除在权威重建之外，产生验证问题</td></tr><tr><td>Digest 不匹配</td><td>保留为完整性失败证据，排除在完整权威集合之外</td></tr><tr><td>缺少签名</td><td>其他要求满足时允许 Core 处理，但不得声称认证完整性</td></tr><tr><td>签名无法验证</td><td>产生签名问题，不得进入认证视图</td></tr><tr><td>相同 ID、相同规范内容</td><td>投影时安全去重，同时保留每个贡献来源的身份</td></tr><tr><td>相同 ID、不同规范内容</td><td>全部变体从权威图隔离，产生严重重复 ID 问题</td></tr><tr><td>缺失引用</td><td>对象保留在 partial 视图，产生未解决引用问题</td></tr><tr><td>流序号缺口</td><td>标记流不完整，不推断缺失对象或迁移</td></tr><tr><td>重复流序号</td><td>保留冲突对象，标记受影响流不符合规范，状态保持 partial 或 disputed</td></tr><tr><td>时间戳冲突</td><td>不把时间戳作为权威，使用序号与 Profile 定义依赖</td></tr><tr><td>非法生命周期迁移</td><td>保留尝试，不改变权威状态，产生生命周期问题</td></tr><tr><td>未授权角色动作</td><td>保留尝试但不应用，产生授权问题</td></tr><tr><td>禁止环</td><td>隔离受影响子图并报告环，继续重建未受影响对象</td></tr><tr><td>并行矛盾复核</td><td>保留全部有效复核，直到出现授权解决对象</td></tr></tbody></table><hr><h1 id="_5-威胁模型与信任假设" tabindex="-1">5. 威胁模型与信任假设 <a class="header-anchor" href="#_5-威胁模型与信任假设" aria-label="Permalink to &quot;5. 威胁模型与信任假设&quot;">​</a></h1><h2 id="_5-1-受保护属性" tabindex="-1">5.1 受保护属性 <a class="header-anchor" href="#_5-1-受保护属性" aria-label="Permalink to &quot;5.1 受保护属性&quot;">​</a></h2><p>TMPA 旨在保护：对象对声明创建者与角色的归属；对象发布后修改的可检测性；生命周期与权限违规的可见性；冲突证据的保留；Runtime 中断后受治理工作的可重建性；执行、复核与批准职责的分离。</p><p>Core <strong>MUST NOT</strong> 把这些结构保证扩大解释为事实真实性、强身份认证或防篡改存储保证。</p><h2 id="_5-2-信任根" tabindex="-1">5.2 信任根 <a class="header-anchor" href="#_5-2-信任根" aria-label="Permalink to &quot;5.2 信任根&quot;">​</a></h2><p>部署 <strong>MUST</strong> 标识其信任根，包括适用的：</p><ul><li>身份提供方；</li><li>角色分配权限；</li><li>Schema 与 Profile 发布权限；</li><li>规范化与完整性 Profile；</li><li>签名密钥与撤销来源；</li><li>存储访问控制；</li><li>时间来源；</li><li>人工批准方或治理机构。</li></ul><p>如果信任根能够被同一攻击者静默改写，TMPA Core 的结构检查不能恢复更强保证。部署 <strong>MUST</strong> 明确说明其信任假设，并 <strong>MUST NOT</strong> 把未声明或未验证的基础设施属性表述为 TMPA Core 保证。</p>`,26)])])}const P=s(l,[["render",i]]);export{u as __pageData,P as default};
